using System.Text;
using System.Text.Json;
using System.Security.Cryptography;
using UnscRelay.Core;
static class NativePackChecks
{
    public static async Task<int> Run(string tools)
    {
        tools=Path.GetFullPath(tools);var root=Path.Combine(Path.GetTempPath(),"relay-native-pack-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);int checks=0;
        void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
        void Reject(Action action,string name){try{action();}catch(Exception ex)when(ex is ArgumentException or CryptographicException or IOException){Check(true,name);return;}throw new Exception("Unexpected acceptance: "+name);}
        var ssh=Path.Combine(tools,"Cygwin","bin","ssh.exe");var keygen=Path.Combine(tools,"Cygwin","bin","ssh-keygen.exe");
        try{
            var algorithms=await NativeClient.Capture(ssh,["-Q","key"]);Check(algorithms.Split('\n').Contains("ssh-mldsa44-ed25519"),"Bundled engine actually offers hybrid SSH signature");Check(algorithms.Contains("sk-ssh-ed25519@openssh.com"),"Bundled engine offers FIDO identities");Check(!algorithms.Contains("ssh-ed448"),"Ed448 is not falsely reported as supported");
            new CertificateProvider{KeyId=Guid.NewGuid().ToString(),Principal="fixture",AuthorityFingerprint="SHA256:"+new string('A',43)}.Validate();Check(true,"Bundled Step defaults use accepted public signing arguments");
            var inc=Path.Combine(root,"included config");await File.WriteAllTextAsync(inc,"Host fixture\n HostName lab.invalid\n User fixture-user\n Port 48221\n");var config=Path.Combine(root,"config");await File.WriteAllTextAsync(config,"Include \""+NativeClient.CygwinPath(inc)+"\"\nMatch host lab.invalid\n ServerAliveInterval 42\nHost fixture\n ProxyCommand echo NEVER_CONNECT\n");
            await NativeClient.Capture(Path.Combine(tools,"Cygwin","bin","chmod.exe"),["600",NativeClient.CygwinPath(config),NativeClient.CygwinPath(inc)]);var before=File.ReadAllBytes(config);var evaluated=await NativeClient.Capture(ssh,["-G","-F",NativeClient.CygwinPath(config),"fixture"]);Check(evaluated.Contains("hostname lab.invalid")&&evaluated.Contains("port 48221")&&evaluated.Contains("user fixture-user"),"Real OpenSSH resolves included endpoint");Check(evaluated.Contains("serveraliveinterval 42"),"Real OpenSSH evaluates Match host");Check(evaluated.Contains("proxycommand echo NEVER_CONNECT"),"ProxyCommand retained by original client");Check(before.SequenceEqual(File.ReadAllBytes(config)),"Config remains byte-for-byte unchanged");
            var native=new ConnectionProfile{Protocol="native",Native=new NativeOptions{Target="fixture",Executable=ssh,ConfigFile=config,IdentityFile="",Signature="ssh-mldsa44-ed25519"},RequirePostQuantumKex=true};await NativeClient.VerifyCapabilities(native);using var launch=NativeClient.Launch(native);Check(launch.Arguments.Contains("PubkeyAcceptedAlgorithms=ssh-mldsa44-ed25519")&&launch.Arguments.Contains("StrictHostKeyChecking=yes"),"Required signature and host-key verification retained");Check(launch.Arguments.Any(a=>a.StartsWith("KexAlgorithms=mlkem")),"Postquantum KEX has no classical fallback");
            Reject(()=>new NativeOptions{Target="-oProxyCommand=bad"}.Validate(),"Option-like target rejected");Reject(()=>new NativeOptions{Target="fixture",ArgumentsJson="[\"-oProxyCommand=bad\"]"}.Validate(),"Raw SSH overrides rejected");Reject(()=>new NativeOptions{Kind="serial",SerialPort="COM1 & bad"}.Validate(),"Serial command injection rejected");
            var rdp=new ConnectionProfile{Protocol="rdp",Host="lab.invalid",Username="fixture",Authentication="password",Rdp=new RdpOptions{Gateway="gateway.invalid",GatewayUsername="gateway-user",MultiMonitor=true,RedirectDrives=true,RedirectSmartCards=true,AudioMode=0}};var document=RdpDocument.Create(rdp,rdp.Host,3389);Check(document.Contains("gatewayusagemethod:i:1")&&document.Contains("use multimon:i:1"),"Gateway enforced and multiple monitors configured");Check(document.Contains("authentication level:i:2")&&document.Contains("enablecredsspsupport:i:1")&&!document.Contains("password"),"RDP document preserves server validation without credentials");Check(document.Contains("redirectsmartcards:i:1")&&document.Contains("drivestoredirect:s:*"),"RDP redirections only as explicitly requested");Reject(()=>(rdp with{JumpHost="other"}).Validate(),"Gateway and SSH tunnel cannot be combined ambiguously");Reject(()=>RdpDocument.Create(rdp with{Username="fixture\r\nauthentication level:i:0"},rdp.Host,3389),"RDP line injection rejected");
            using var vault=new KeyVault(Path.Combine(root,"vault"));vault.Unlock("Native pack fixture master password!");var user=KeyGeneration.Generate(vault,"user","ed25519");var caFile=Path.Combine(root,"ca");await NativeClient.Capture(keygen,["-q","-t","ed25519","-N","","-f",NativeClient.CygwinPath(caFile)]);var caBytes=File.ReadAllBytes(caFile);KeyInfo ca;try{ca=vault.Import("ca",caBytes);}finally{CryptographicOperations.ZeroMemory(caBytes);}
            await NativeClient.Capture(Path.Combine(tools,"Cygwin","bin","chmod.exe"),["600",NativeClient.CygwinPath(caFile)]);var provider=new CertificateProvider{KeyId=user.Id,Executable=keygen,Principal="fixture",AuthorityFingerprint=ca.Fingerprint,Hours=1,ArgumentsJson=JsonSerializer.Serialize(new[]{"-q","-s",caFile,"-I","fixture-cert","-n","{principal}","-V","+{hours}h","{publicKey}"})};
            var privateBefore=SHA256.HashData(vault.Read(user.Id));var issued=await ExternalCertificates.Issue(vault,provider,Path.Combine(root,"requests"));Check(issued.Certificate?.AuthorityFingerprint==ca.Fingerprint,"External signer produces matching validated certificate");Check(privateBefore.SequenceEqual(SHA256.HashData(vault.Read(user.Id))),"External signer keeps private key in vault");Check(Directory.GetDirectories(Path.Combine(root,"requests")).Length==0,"Public request scratch cleaned up");
            var text=issued.Certificate!.Text;Reject(()=>ExternalCertificates.ValidateCertificate(text,provider with{AuthorityFingerprint=user.Fingerprint},DateTimeOffset.UtcNow),"Unexpected CA rejected before attachment");Reject(()=>ExternalCertificates.ValidateCertificate(text,provider with{Principal="other"},DateTimeOffset.UtcNow),"Unexpected principal rejected");var parts=text.Split(' ');var blob=Convert.FromBase64String(parts[1]);blob[^1]^=1;parts[1]=Convert.ToBase64String(blob);Reject(()=>ExternalCertificates.ValidateCertificate(string.Join(' ',parts),provider,DateTimeOffset.UtcNow),"Altered certificate signature rejected");
            vault.RevokeCertificate(user.Id,"fixture revocation");try{await ExternalCertificates.Issue(vault,provider,Path.Combine(root,"requests"));throw new Exception("Revoked renewed");}catch(InvalidOperationException){Check(true,"Revoked certificate never automatically renewed");}
            var hybrid=Path.Combine(root,"hybrid");var gen=Path.Combine(tools,"Cygwin","bin","ssh-keygen.exe");await NativeClient.Capture(gen,["-q","-t","mldsa44-ed25519","-N","","-f",NativeClient.CygwinPath(hybrid)]);await NativeClient.Capture(Path.Combine(tools,"Cygwin","bin","chmod.exe"),["600",NativeClient.CygwinPath(hybrid)]);var hybridPub=File.ReadAllText(hybrid+".pub");Check(hybridPub.StartsWith("ssh-mldsa44-ed25519 "),"Hybrid private/public keys really generated by bundled backend");
            var message=Path.Combine(root,"message");await File.WriteAllTextAsync(message,"fixture signing payload");await NativeClient.Capture(gen,["-Y","sign","-f",NativeClient.CygwinPath(hybrid),"-n","fixture",NativeClient.CygwinPath(message)]);var allowed=Path.Combine(root,"allowed");await File.WriteAllTextAsync(allowed,"fixture "+hybridPub);var verified=await NativeClient.Capture(gen,["-Y","verify","-f",NativeClient.CygwinPath(allowed),"-I","fixture","-n","fixture","-s",NativeClient.CygwinPath(message+".sig")],inputText:"fixture signing payload");Check(verified.Contains("Good"),"Real hybrid signature verifies with original OpenSSH");
            var store=new ProfileStore(root);var data=new AppData{Profiles=[native,rdp],CertificateProviders=[provider with{AutoRenew=true}]};store.Save(data);var loaded=store.Load();Check(loaded.Profiles[0].Native.ConfigFile==config&&loaded.Profiles[1].Rdp.Gateway=="gateway.invalid"&&loaded.CertificateProviders.Single().AutoRenew,"Native and RDP options and CA policy survive reopening");
            var backup=UpdateBackup.Create(root,"fixture");Check(File.Exists(Path.Combine(backup,"profiles.json")),"Update backup preserves expanded profile data");
            Console.WriteLine(checks+" native pack checks passed");return 0;
        }finally{if(Path.GetFullPath(root).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(root).StartsWith("relay-native-pack-"))Directory.Delete(root,true);}
    }
}
